from pathlib import Path
processes = {}
for proc in Path('/proc').iterdir():
    if not proc.name.isdigit(): continue
    try:
        args = (proc/'cmdline').read_bytes().decode().split('\\0')[:-1]
        ppid = int(next(line for line in (proc/'status').read_text().splitlines() if line.startswith('PPid:')).split()[1])
        processes[int(proc.name)] = (ppid, args)
    except (OSError, StopIteration, UnicodeError): pass
roots = {pid for pid, (_, args) in processes.items() if any(arg.endswith('/pr_open.py') for arg in args[:3])}
selected = set(roots)
for _ in range(7):
    selected |= {pid for pid, (parent, _) in processes.items() if parent in selected}
for pid in sorted(selected):
    parent, args = processes[pid]
    print(pid, parent, ' '.join(args)[:250])
